package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;import java.util.*;
/** Exact internal adapter routes; real service identity is required before reading any request bytes. */
@RestController @ConditionalOnExpression("${medical.model-runtime.enabled:false} and ${medical.formal-invocation.enabled:false}")
public final class FormalInvocationController {
 private final ServiceCertificateIdentity identities;private final FormalInvocationService service;private final FormalInvocationHttpSchema schema;private final FormalInvocationSchema json;
 public FormalInvocationController(ServiceCertificateIdentity identities,FormalInvocationService service,FormalInvocationHttpSchema schema,FormalInvocationSchema json){this.identities=identities;this.service=service;this.schema=schema;this.json=json;}
 @PostMapping(value="/internal/v1/invocations",consumes="application/json")
 public JsonNode reserve(HttpServletRequest request,HttpServletResponse response)throws Exception{identities.require(request);headers(request,true);var b=schema.read("Reserve",body(request));var r=service.reserveExpected(request,request.getHeader("X-Run-Token"),schema.action(b),b.required("model_config_revision").textValue(),b.required("context_manifest_id").textValue(),b.required("request_parameters"));var data=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("invocation_id",r.invocationId()).put("verification_id",r.verificationId()).put("status",r.status()).put("lease_generation",r.leaseGeneration().toString());return output(response,data);}
 @PostMapping(value="/internal/v1/invocations/{id}/begin-send",consumes="application/json")
 public JsonNode begin(HttpServletRequest request,HttpServletResponse response,@PathVariable("id")String id)throws Exception{identities.require(request);headers(request,true);WireValues.uuid(id);var b=schema.read("BeginSend",body(request));var permit=service.beginDispatch(request,request.getHeader("X-Run-Token"),schema.action(b),id);var data=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("invocation_id",id).put("new_send_admission",permit.isPresent());
  if(permit.isPresent()){var p=permit.get();var actual=p.claimProviderBody();data.put("tenant_id",p.tenantId()).put("original_actor_id",p.originalActorId()).put("context_manifest_id",p.contextManifestId()).put("model_config_revision",p.modelConfigRevision()).put("dispatch_attempt_id",p.attemptId()).put("dispatch_generation","1").put("service_uri",p.serviceUri()).put("deadline_at",p.deadline().toInstant(java.time.ZoneOffset.UTC).toString()).put("credential_reference_id",p.credentialReferenceId()).put("credential_revision",p.credentialRevision()).put("canonical_provider_body_sha256",p.canonicalProviderBodySha256());data.set("provider_body",actual);}else{data.putNull("tenant_id").putNull("original_actor_id").putNull("context_manifest_id").putNull("model_config_revision").putNull("dispatch_attempt_id").put("dispatch_generation","1").putNull("service_uri").putNull("deadline_at").putNull("credential_reference_id").putNull("credential_revision").putNull("canonical_provider_body_sha256").putNull("provider_body");}
  return output(response,data);
 }
 @PostMapping(value="/internal/v1/invocations/{id}/receipts",consumes="application/json")
 public JsonNode receipts(HttpServletRequest request,HttpServletResponse response,@PathVariable("id")String id)throws Exception{identities.require(request);headers(request,false);WireValues.uuid(id);var b=schema.read("Receipt",body(request));var r=service.recordOutcome(request,b.required("tenant_id").textValue(),b.required("original_actor_id").textValue(),id,ContentReadAuthorization.canonicalBytes(b.required("model_result")),ContentReadAuthorization.canonicalBytes(b.required("provider_capture")));return output(response,r.receipt());}
 static byte[] body(HttpServletRequest request)throws java.io.IOException{int maximum=16777216;if(request.getContentLengthLong()>maximum)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);var b=request.getInputStream().readNBytes(maximum+1);if(b.length>maximum)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);return b;}
 private static void headers(HttpServletRequest r,boolean token){if(r.getQueryString()!=null)throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);for(String h:token?List.of("X-Schema-Version","X-Run-Token"):List.of("X-Schema-Version")){var v=r.getHeaders(h);if(v==null||!v.hasMoreElements())throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);String first=v.nextElement();if(first==null||first.isBlank()||v.hasMoreElements())throw new TenantAccessException(ErrorCode.SCHEMA_INVALID);}if(!"1.0.0".equals(r.getHeader("X-Schema-Version")))throw new TenantAccessException(ErrorCode.SCHEMA_UNSUPPORTED);}
 private JsonNode output(HttpServletResponse response,JsonNode data)throws Exception{return FormalInvocationResponses.envelope(data,"1",response);}

 @ExceptionHandler(TenantAccessException.class)void denied(TenantAccessException e,HttpServletResponse response)throws java.io.IOException{new IdentityErrorResponseWriter().write(response,switch(e.code()){case ACCESS_DENIED->403;case DEPENDENCY_UNAVAILABLE->503;case FILE_TOO_LARGE,CONTEXT_LIMIT->413;case REVISION_CONFLICT,IDEMPOTENCY_CONFLICT,ACTION_STALE,LEASE_STALE,SCOPE_STALE,CONTEXT_CHANGED->409;default->422;},e.code());}
}
